def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def value(row, key):
        val = row.get(key, "")
        return "" if val is None else str(val)

    def normalize_email(raw):
        raw = raw.strip()
        match = re.search(r"<([^<>]*)>", raw)
        if match:
            raw = match.group(1)
        raw = raw.strip().lower()

        if raw.count("@") != 1:
            return "", False

        local, domain = raw.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            raw = f"{local}@{domain}"

        valid = (
            raw.count("@") == 1
            and bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )
        return raw, valid

    def normalize_phone(raw):
        raw = raw.strip()
        marker = re.search(r"x|ext|#", raw, re.IGNORECASE)
        if marker:
            raw = raw[:marker.start()]
        digits = "".join(ch for ch in raw if ch.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        valid = len(digits) == 10 and digits[0] not in "01"
        return digits, valid

    def normalize_zip(raw):
        zip_code = raw.strip()
        if "-" in zip_code:
            zip_code = zip_code.split("-", 1)[0]
        if len(zip_code) == 4 and zip_code.isdigit():
            zip_code = "0" + zip_code
        return zip_code if len(zip_code) == 5 and zip_code.isdigit() else ""

    def normalize_name(raw):
        name = raw.strip()
        if name and (name.isupper() or name.islower()):
            name = name.title()
        return name

    def parse_updated(raw):
        raw = raw.strip()
        if "T" in raw:
            return datetime.strptime(raw, "%Y-%m-%dT%H:%M:%S")
        if "/" in raw:
            return datetime.strptime(raw, "%m/%d/%Y")
        return datetime.strptime(raw, "%Y-%m-%d")

    normalized = []
    for index, row in enumerate(rows):
        email, email_valid = normalize_email(value(row, "email"))
        phone, phone_valid = normalize_phone(value(row, "phone"))
        if not email_valid and not phone_valid:
            continue

        normalized.append({
            "index": index,
            "first_name": normalize_name(value(row, "first_name")),
            "last_name": normalize_name(value(row, "last_name")),
            "email": email if email_valid else "",
            "phone": phone if phone_valid else "",
            "zip": normalize_zip(value(row, "zip")),
            "source": value(row, "source").strip().lower(),
            "updated_dt": parse_updated(value(row, "updated")),
            "opted_out": value(row, "opted_out").strip().lower() in {
                "y", "yes", "true", "1"
            },
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", value(row, "tags"))
                if tag.strip()
            },
        })

    # Union-find makes identity matching transitive.
    parent = list(range(len(normalized)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    by_email = {}
    by_phone_last_name = {}
    for i, person in enumerate(normalized):
        if person["email"]:
            if person["email"] in by_email:
                union(i, by_email[person["email"]])
            else:
                by_email[person["email"]] = i

        if person["phone"] and person["last_name"]:
            key = (person["phone"], person["last_name"].lower())
            if key in by_phone_last_name:
                union(i, by_phone_last_name[key])
            else:
                by_phone_last_name[key] = i

    groups = {}
    for i, person in enumerate(normalized):
        groups.setdefault(find(i), []).append(person)

    def pick(group, field, valid_only=False):
        candidates = [
            person for person in group
            if person[field] and (not valid_only or person[field])
        ]
        if not candidates:
            return ""
        winner = min(
            candidates,
            key=lambda person: (
                person["source"] != "manual",
                -person["updated_dt"].timestamp(),
                person["index"],
            ),
        )
        return winner[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(p["index"] for p in g)):
        latest = max(person["updated_dt"] for person in group)
        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(set().union(*(p["tags"] for p in group)))),
            "opted_out": "Y" if any(p["opted_out"] for p in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
